text:
Here's a simple water tracker with a goal of 8 glasses. Tap + after each glass, and it starts again each new day.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  body { font-family: sans-serif; text-align: center; padding: 24px; background: #eef6fb; color: #123; }
  h1 { font-size: 22px; margin-bottom: 4px; }
  #count { font-size: 56px; margin: 12px 0 4px; }
  #msg { min-height: 24px; margin-bottom: 16px; }
  #glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; max-width: 280px; margin: 0 auto 20px; }
  .g { width: 56px; height: 56px; border-radius: 10px; border: 2px solid #4a9fd4; background: #fff; }
  .g.full { background: #4a9fd4; }
  button { font-size: 18px; padding: 10px 20px; margin: 4px; border: 0; border-radius: 8px; background: #2278b5; color: #fff; }
  button.alt { background: #8aa; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="glasses"></div>
  <button id="add">+ Add a glass</button>
  <button id="sub" class="alt">- Undo</button>
  <button id="reset" class="alt">Reset</button>
<script>
  var GOAL = 8;
  var today = new Date().toDateString();
  var n = 0;
  try {
    if (localStorage.getItem("waterDay") === today) {
      n = parseInt(localStorage.getItem("waterCount"), 10) || 0;
    }
  } catch (e) {}

  function save() {
    try {
      localStorage.setItem("waterDay", today);
      localStorage.setItem("waterCount", String(n));
    } catch (e) {}
  }

  function draw() {
    document.getElementById("count").textContent = n + " / " + GOAL;
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var d = document.createElement("div");
      d.className = "g" + (i < n ? " full" : "");
      box.appendChild(d);
    }
    var left = GOAL - n;
    document.getElementById("msg").textContent =
      left > 0 ? left + " more to reach your goal" : "Goal reached. Well done!";
  }

  document.getElementById("add").onclick = function () { n++; save(); draw(); };
  document.getElementById("sub").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```

